#define main inherited_scan_main
#include "scan_endpoints.cpp"
#undef main
string aug(const array<int,8>&A,int s,int t){vector<vector<int>>cells;string sig=signature(A,s,t,cells);vector<vector<int>>tr;for(auto&b:cells)if(b.size()==3)tr.push_back(b);int chir=0;if(tr.size()==2){auto X=tr[0],Y=tr[1];int q=0;for(int v:Y)q+=(A[X[0]]>>v)&1;if(q==1||q==2){int u=X[0],w=-1,pu=-1,pw=-1;for(int v:X)if(A[u]>>v&1)w=v;for(int v:Y){if(((A[u]>>v)&1)==(q==1))pu=v;if(((A[w]>>v)&1)==(q==1))pw=v;}chir=(A[pu]>>pw&1)?1:2;}}sig.push_back(chir);return sig;}
void need(bool x,string s){if(!x){cerr<<s<<"\n";exit(2);}}
int main(int argc,char**argv){need(argc==5,"usage: classes.tsv masks.raw edges.tsv ports.tsv");ifstream f(argv[1]);string line;getline(f,line);vector<unsigned>codes;vector<int>conv,node;while(getline(f,line)){stringstream ss(line);int ci,input,co,no;unsigned ca;ss>>ci>>ca>>input>>co>>no;need(ci==(int)codes.size(),"class order");codes.push_back(ca);conv.push_back(co);node.push_back(no);}need(codes.size()==6880,"class count");unordered_map<string,int>lookup;long long ep=0;
for(int ci=0;ci<6880;ci++){array<int,8>A{};int k=27;for(int i=0;i<8;i++)for(int j=i+1;j<8;j++,k--)if(codes[ci]>>k&1)A[i]|=1<<j;else A[j]|=1<<i;
for(int s=0;s<8;s++){int dp[256]{};dp[1<<s]=1<<s;for(int m=1;m<256;m++)for(int v=0;v<8;v++)if(dp[m]>>v&1){int q=A[v]&~m;while(q){int b=q&-q;q-=b;dp[m|b]|=b;}}for(int t=0;t<8;t++)if(dp[255]>>t&1){ep++;auto sig=aug(A,s,t);auto it=lookup.find(sig);need(it==lookup.end()||it->second==ci,"augmented signature cross-class collision");lookup[sig]=ci;}}}
ifstream mf(argv[2],ios::binary);vector<unsigned char>raw((istreambuf_iterator<char>(mf)),{});need(raw.size()==(1<<22),"complete mask data");vector<int>truth(1<<21),decoded(1<<21);for(int m=0;m<(1<<21);m++)truth[m]=raw[2*m]+256*raw[2*m+1];
vector<pair<int,int>>tiles;for(int i=0;i<6;i++)for(int j=i+2;j<8;j++)tiles.push_back({i,j});vector<int>ref;for(auto [i,j]:tiles)ref.push_back(find(tiles.begin(),tiles.end(),pair<int,int>{7-j,7-i})-tiles.begin());
for(int m=0;m<(1<<21);m++){array<int,8>A{};for(int v=1;v<8;v++)A[v]|=1<<(v-1);for(int k=0;k<21;k++){auto [i,j]=tiles[k];if(m>>k&1)A[i]|=1<<j;else A[j]|=1<<i;}auto sig=aug(A,7,0);auto it=lookup.find(sig);need(it!=lookup.end(),"literal signature lookup missing");decoded[m]=it->second;need(decoded[m]==truth[m],"literal target class mismatch");}
map<pair<int,int>,array<int,2>>edges;map<array<int,5>,int>ports;long long blue=0,black=0,loops=0,refchecks=0;int F=(1<<21)-1;
for(int m=0;m<=F;m++){int refl=0;for(int k=0;k<21;k++)if(m>>k&1)refl|=1<<ref[k];need(decoded[refl]==conv[decoded[m]],"converse reflection mismatch");refchecks++;if(!(m>>5&1))continue;int ci=decoded[m],cj=decoded[m^F],u=node[ci],v=node[cj];bool b=m==refl;int s=7,t=0;for(int k=0;k<21;k++)if(m>>k&1){if(tiles[k].second==7)s--;if(tiles[k].first==0)t++;}edges[{u,v}][b?0:1]++;ports[{ci,cj,s,t,int(b)}]++;if(b)blue++;else black++;if(u==v)loops++;}
map<pair<int,int>,array<int,2>>ee;ifstream ef(argv[3]);getline(ef,line);while(getline(ef,line)){stringstream ss(line);int u,v,b,k;ss>>u>>v>>b>>k;ee[{u,v}]={b,k};}need(edges==ee,"exact full merged edge ledger mismatch");
map<array<int,5>,int>pp;ifstream pf(argv[4]);getline(pf,line);while(getline(pf,line)){stringstream ss(line);array<int,5>key;int z;for(int&i:key)ss>>i;ss>>z;pp[key]=z;}need(ports==pp,"exact full ordinary endpoint port ledger mismatch");
cout<<"{\"status\":\"PASS\",\"classes\":6880,\"endpoint_pairs\":"<<ep<<",\"signature_lookup\":"<<lookup.size()<<",\"literal_masks\":"<<(1<<21)<<",\"class_mismatches\":0,\"converse_checks\":"<<refchecks<<",\"ordinary_port_entries\":"<<ports.size()<<",\"merged_edge_entries\":"<<edges.size()<<",\"blue_lines\":"<<blue<<",\"black_lines\":"<<black<<",\"loop_lines\":"<<loops<<"}\n";
}
